import 'package:flutter/foundation.dart';

import '../platform/sound.dart';
import 'rules/models.dart';

export '../platform/sound.dart' show SoundLoop;

/// The game's chiptune sound effects and background music, generated by
/// `tool/sounds/generate.py`. Each is off until the player turns it on in
/// the account menu; the device remembers them.
class GameSound {
  GameSound._(this._output)
    : music = ValueNotifier(_output.savedOn('music')),
      effects = ValueNotifier(_output.savedOn('effects'));

  /// The one for the whole app.
  static final instance = GameSound._(SoundOutput());

  final SoundOutput _output;

  /// Whether the background music is on.
  final ValueNotifier<bool> music;

  /// Whether the sound effects are on.
  final ValueNotifier<bool> effects;

  /// The sound effects played, newest last (with them on), for tests.
  @visibleForTesting
  final played = <String>[];

  /// The background music.
  static const musicFile = 'music.wav';

  /// Every sound effect, the most frequent first: downloaded and decoded as
  /// soon as sound effects are on, so each plays right on time (one that
  /// isn't ready in time is skipped rather than played late).
  static final effectFiles = [
    'ui_tap.mp3',
    'ui_confirm.mp3',
    'reward.mp3',
    'summon_land.mp3',
    'summon_tape.wav',
    'summon_cut.mp3',
    for (final rarity in Rarity.values) ...[
      'summon_shake_${rarity.name}.mp3',
      'summon_open_${rarity.name}.mp3',
      'summon_beam_${rarity.name}.mp3',
      'summon_reveal_${rarity.name}.mp3',
    ],
    'summon_flip.mp3',
    'timer_tick.mp3',
    'timer_final.mp3',
    'time_up.mp3',
    'drawing_saved.mp3',
    'star_drop.mp3',
    'fight_drop.mp3',
    'fight_rise.mp3',
    'fight_call.mp3',
    'fight_swing.mp3',
    'fight_hit.mp3',
    'fight_hit_hard.mp3',
    'fight_ko.mp3',
    'fight_win.mp3',
    'fight_lose.mp3',
    'unlock.mp3',
  ];

  static const _musicVolume = 0.35;
  static const _duckedVolume = 0.08;

  SoundLoop? _music;
  int _ducks = 0;

  void toggleMusic() => setMusic(!music.value);

  void setMusic(bool on) {
    if (on) _output.wake();
    music.value = on;
    _output.save('music', on);
    startMusic();
  }

  void toggleEffects() => setEffects(!effects.value);

  void setEffects(bool on) {
    if (on) {
      _output
        ..wake()
        ..preload(effectFiles);
    }
    effects.value = on;
    _output.save('effects', on);
  }

  /// Gets the sounds turned on ready ahead of time, e.g. as the game starts.
  void preload() {
    if (effects.value) _output.preload(effectFiles);
    if (music.value) _output.preload([musicFile]);
  }

  /// Starts the background music if it's on (stops it if off).
  void startMusic() {
    if (!music.value) {
      _music?.stop();
      _music = null;
    } else {
      _music ??= _output.loop(musicFile, volume: _ducks > 0 ? _duckedVolume : _musicVolume);
    }
  }

  /// Turns the music down while a screen with sounds of its own is open,
  /// until [unduck].
  void duck() {
    _ducks++;
    _music?.volume = _duckedVolume;
  }

  void unduck() {
    if (_ducks > 0) _ducks--;
    if (_ducks == 0) _music?.volume = _musicVolume;
  }

  /// Plays [file] of `assets/sounds/` once, if sound effects are on.
  void play(String file, {double volume = 1}) {
    if (!effects.value) return;
    played.add(file);
    _output.play(file, volume: volume);
  }

  /// Plays [file] over and over if sound effects are on, until stopped.
  SoundLoop? loop(String file, {double volume = 1}) {
    if (!effects.value) return null;
    played.add(file);
    return _output.loop(file, volume: volume);
  }

  // Buttons, through the theme's splash.
  void buttonTap() => play('ui_tap.mp3', volume: 0.6);
  void buttonConfirm() => play('ui_confirm.mp3', volume: 0.7);

  // The drawing step.
  void timerTick() => play('timer_tick.mp3', volume: 0.7);
  void timerFinal() => play('timer_final.mp3');
  void timeUp() => play('time_up.mp3');
  void drawingSaved() => play('drawing_saved.mp3');

  // Boosting.
  void starDrop() => play('star_drop.mp3');

  // Fights: the entrance, every swing and blow, and the verdict.
  void challengerDrops() => play('fight_drop.mp3', volume: 0.8);
  void fighterRises() => play('fight_rise.mp3', volume: 0.7);
  void fightCall() => play('fight_call.mp3');
  void swing() => play('fight_swing.mp3', volume: 0.6);
  void blow({required bool hard}) => play(hard ? 'fight_hit_hard.mp3' : 'fight_hit.mp3');
  void knockout() => play('fight_ko.mp3');
  void fightResult({required bool won}) => play(won ? 'fight_win.mp3' : 'fight_lose.mp3');

  // Rewards: pulls or stars received, an upgrade unlocked.
  void reward() => play('reward.mp3');
  void unlock() => play('unlock.mp3');

  // The summon, for the rarest card in the box.
  void boxLands() => play('summon_land.mp3');
  SoundLoop? tapeTearing() => loop('summon_tape.wav', volume: 0);
  void tapeCut() => play('summon_cut.mp3');
  void boxShakes(Rarity rarity) => play('summon_shake_${rarity.name}.mp3');
  void boxOpens(Rarity rarity) => play('summon_open_${rarity.name}.mp3');
  void cardRises(Rarity rarity) => play('summon_beam_${rarity.name}.mp3', volume: 0.8);
  void cardFlips() => play('summon_flip.mp3', volume: 0.8);
  void cardRevealed(Rarity rarity) => play('summon_reveal_${rarity.name}.mp3');
}

/// The app's [GameSound].
GameSound get sound => GameSound.instance;
